alter policy room_moderation_log_read on public.room_moderation_log to authenticated using (exists(select 1 from public.rooms r where r.id=room_moderation_log.room_id and r.owner_id=(select auth.uid())) or exists(select 1 from public.room_members m where m.room_id=room_moderation_log.room_id and m.user_id=(select auth.uid()) and m.role='moderator')); alter policy game_results_select_own on public.game_results to authenticated using(user_id=(select auth.uid())); create index if not exists room_moderation_log_room_idx on public.room_moderation_log(room_id);
